function quadrato(lato)
  for count3 = 1, math.floor(lato) do
    for count = 1, math.floor(lato) do
      byte.placeDown()
      byte.forward()
    end
    for count2 = 1, math.floor(lato) do
      byte.back()
    end
    byte.turnRight()
    byte.forward()
    byte.turnLeft()
  end
  byte.turnLeft()
  for count4 = 1, math.floor(lato) do
    byte.forward()
  end
  byte.turnRight()
end


function stratoSuccessivo()
  byte.up()
  byte.forward()
  byte.turnRight()
  byte.forward()
  byte.turnLeft()
end



